-- Question 2.2: total population inside the user's eastern Saudi polygon.
-- This estimates all residents in the area, not individual religious affiliation.
SELECT
    CAST(SUM(population) AS BIGINT) AS population
FROM full_2020
WHERE month = '2019-06'
  AND country = 'SAU'
  AND type = 'total_population'
  AND ST_Within(
    ST_Point(longitude, latitude),
    ST_Polygon('POLYGON ((48.6598654 28.0143251,48.6569612 27.3805309,48.7497323 25.1864954,49.0478517 24.3243216,49.3025082 23.4251172,49.6417161 23.3488573,49.9221675 23.3825127,50.1040064 23.5086925,50.167355 23.7463357,50.1526499 24.1315913,50.2158789 24.3141526,50.4607728 24.4576498,50.6273167 24.6938309,50.6520847 24.9137668,50.5764085 25.1902945,50.4790486 25.4120482,50.278625 25.5982137,50.1193036 25.8205879,50.5708008 25.8709147,50.6617316 26.2386043,50.4190005 26.425948,50.1102231 26.4289038,49.9902194 26.6146583,50.1153391 26.6875904,49.9940467 26.8181128,49.7485183 26.9495016,49.5849354 27.0616984,49.6718234 27.3210691,49.4017972 27.2853281,49.3006882 27.4902695,49.01142 27.6402373,48.8040562 27.7152972,48.6598654 28.0143251))')
  );
